        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.fiscalCode = container.decodeLenient(String.self, forKey: .fiscalCode)
        self.surname = container.decodeLenient(String.self, forKey: .surname)
        self.name = container.decodeLenient(String.self, forKey: .name)
        self.birthDate = container.decodeLenient(String.self, forKey: .birthDate)
        self.studentEnrollment = container.decodeLenient([Esse3StudentEnrollment].self, forKey: .studentEnrollment) ?? []
    }

